<script setup lang="ts">
import { reactive,ref } from 'vue';import { useAuthStore } from '#/store';
defineOptions({name:'Login'});const authStore=useAuthStore();const form=reactive({username:'',password:''});const visible=ref(false),error=ref(''),caps=ref(false);
async function submit(){if(authStore.loginLoading)return;error.value='';if(!form.username.trim()||!form.password){error.value='请填写账号和密码';return}try{await authStore.authLogin({username:form.username.trim(),password:form.password})}catch{error.value='登录未成功，请核对账号、密码或稍后重试。'}}
</script>
<template><div class="login-form"><img class="mobile-logo" src="/logo.svg" alt="织愈"/><p class="login-kicker">WELCOME BACK</p><h2>欢迎回到织愈</h2><p class="login-desc">登录工作空间，开始今天的创作与协作。</p><form @submit.prevent="submit"><label for="zy-user">工作账号</label><div class="input-wrap"><span aria-hidden="true">◎</span><input id="zy-user" v-model="form.username" name="username" autocomplete="username" placeholder="请输入账号" :disabled="authStore.loginLoading"/></div><label for="zy-password">登录密码</label><div class="input-wrap"><span aria-hidden="true">⌑</span><input id="zy-password" v-model="form.password" name="password" :type="visible?'text':'password'" autocomplete="current-password" placeholder="请输入密码" :disabled="authStore.loginLoading" @keyup="caps=$event.getModifierState('CapsLock')"/><button class="reveal" type="button" :aria-label="visible?'隐藏密码':'显示密码'" :aria-pressed="visible" @click="visible=!visible">{{visible?'隐藏':'显示'}}</button></div><p v-if="caps" class="caps">大写锁定已开启</p><p v-if="error" class="login-error" role="alert">{{error}}</p><button class="login-submit" type="submit" :disabled="authStore.loginLoading">{{authStore.loginLoading?'正在登录…':'登录工作空间'}} <span v-if="!authStore.loginLoading">→</span></button></form><div class="login-divider"></div><p class="login-help">供管理员、传承人与咨询师使用。<br/>账号问题请联系平台管理员。</p><div class="login-tags"><span>内容管理</span><i></i><span>活动协作</span><i></i><span>授权访问</span></div></div></template>
<style scoped>.login-form{color:#243d31}.mobile-logo{display:none;width:52px;margin-bottom:26px}.login-kicker{font-size:10px;letter-spacing:3px;color:#8b9b8c;margin-bottom:18px}.login-form h2{font-size:30px;font-weight:550;letter-spacing:1px}.login-desc{font-size:12px;color:#8b968d;margin-top:13px;margin-bottom:40px}.login-form label{display:block;font-size:12px;font-weight:550;margin:24px 0 10px}.input-wrap{display:flex;align-items:center;gap:12px;height:52px;padding:0 15px;background:white;border:1px solid #dce3d9;border-radius:10px;transition:border-color .2s,box-shadow .2s}.input-wrap:focus-within{border-color:#588a6c;box-shadow:0 0 0 3px #54886c14}.input-wrap>span{color:#8a9f8d;font-size:21px}.input-wrap input{flex:1;min-width:0;background:transparent;font-size:13px;outline:none;color:#203c2e;height:100%}.input-wrap input::placeholder{color:#a3ada4}.reveal{font-size:11px;color:#66836c;padding:6px}.login-submit{display:flex;justify-content:space-between;align-items:center;background:#2d624b;color:#fff;width:100%;height:52px;margin-top:30px;padding:0 20px;border-radius:10px;font-size:13px;box-shadow:0 7px 15px #244a3520;transition:background .2s}.login-submit:hover{background:#214e3b}.login-submit:disabled{opacity:.6}.login-divider{height:1px;background:#e4e8df;margin:32px 0 20px}.login-help{font-size:11px;line-height:2;color:#8a958c}.login-tags{display:flex;gap:13px;align-items:center;font-size:10px;color:#718570;margin-top:20px}.login-tags i{width:3px;height:3px;background:#b7c4b5;border-radius:50%}.login-error,.caps{font-size:12px;color:#a45039;margin-top:12px;line-height:1.7}button:focus-visible{outline:3px solid #9ac1a4;outline-offset:3px}@media(max-width:900px){.mobile-logo{display:block}}
</style>
